import{_ as e,o as a,c as d,ai as n}from"./chunks/framework.XEs52zTF.js";const b=JSON.parse('{"title":"理解 LL 与 LR","description":"","frontmatter":{"title":"理解 LL 与 LR","chapterId":"chapter08","prev":{"text":"递归下降与表达式","link":"/chapter07"},"next":{"text":"AST 与友好的错误","link":"/chapter09"}},"headers":[],"relativePath":"chapter08.md","filePath":"chapter08.md"}'),s={name:"chapter08.md"};function r(o,t,p,c,l,i){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="第08章-ll、lr-与通用语法分析的地图" tabindex="-1">第08章 LL、LR 与通用语法分析的地图 <a class="header-anchor" href="#第08章-ll、lr-与通用语法分析的地图" aria-label="Permalink to &quot;第08章 LL、LR 与通用语法分析的地图&quot;">​</a></h1><h2 id="本章目标与前置" tabindex="-1">本章目标与前置 <a class="header-anchor" href="#本章目标与前置" aria-label="Permalink to &quot;本章目标与前置&quot;">​</a></h2><p>你已经写过递归下降解析器。本章把“凭代码判断走哪一支”提升为“根据集合和状态表机械决定”。重点完成两个可手算实验：为简单表达式文法计算 FIRST/FOLLOW 并建立 LL 预测表；为一个极小左递归文法建立 LR 项目集并完成移进归约。最后比较 Earley、CYK、GLR、PEG 与生成器的适用场景。</p><p>不必为了证明自己学会理论，立刻重写 Sprout 前端。手写前端的可维护性与文法理论的可推导性可以互相验证。</p><h2 id="_8-1-cfg-的四个部件" tabindex="-1">8.1 CFG 的四个部件 <a class="header-anchor" href="#_8-1-cfg-的四个部件" aria-label="Permalink to &quot;8.1 CFG 的四个部件&quot;">​</a></h2><p>上下文无关文法由非终结符集合、终结符集合、产生式集合和开始符号组成。产生式左边只有一个非终结符，右边是一串终结符与非终结符。推导反复替换非终结符，最终得到终结符串。</p><p>LL 中第一个 L 表示从左向右读输入，第二个 L 表示构造最左推导；LR 的 R 表示最右推导的逆过程。括号里的 k 表示决定下一步时使用多少个向前看符号。它们描述的是文法与分析方式，不是“一个适合简单语言，一个适合复杂语言”这样的模糊排名。</p><p>同一种语言可以有不同文法。某文法不满足 LL(1)，不代表这个语言永远无法用另一份 LL(1) 文法描述；有二义性的文法也不等于这个语言必定固有二义。讨论理论结论时先说明对象是语言还是文法。</p><h2 id="_8-2-first-从这里可能先看见什么" tabindex="-1">8.2 FIRST：从这里可能先看见什么 <a class="header-anchor" href="#_8-2-first-从这里可能先看见什么" aria-label="Permalink to &quot;8.2 FIRST：从这里可能先看见什么&quot;">​</a></h2><p>使用下面的表达式文法，<code>n</code> 表示整数 Token，<code>$</code> 表示输入结束：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E  → T E&#39;</span></span>
<span class="line"><span>E&#39; → + T E&#39; | ε</span></span>
<span class="line"><span>T  → F T&#39;</span></span>
<span class="line"><span>T&#39; → * F T&#39; | ε</span></span>
<span class="line"><span>F  → ( E ) | n</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>FIRST(X) 是 X 可推导出的串中可能出现的第一个终结符；如果 X 能推出空串，还记录 ε。由 F 的两个分支直接得到 <code>FIRST(F) = {(, n}</code>。T 先读F，而F不能空，所以 <code>FIRST(T) = {(, n}</code>；E 同理。<code>FIRST(E&#39;) = {+, ε}</code>，<code>FIRST(T&#39;) = {*, ε}</code>。</p><p>对于串 <code>X Y Z</code>，先加入 FIRST(X) 中非空的元素；只有 X 可空时，才继续看 Y；若前面都可空，才继续看 Z。不能简单把所有 FIRST 集合无条件求并集，否则会引入根本不可能出现在开头的符号。</p><h2 id="_8-3-follow-这个结构后面可能是什么" tabindex="-1">8.3 FOLLOW：这个结构后面可能是什么 <a class="header-anchor" href="#_8-3-follow-这个结构后面可能是什么" aria-label="Permalink to &quot;8.3 FOLLOW：这个结构后面可能是什么&quot;">​</a></h2><p>FOLLOW(A) 收集在某个合法句型中可能紧跟 A 的终结符。开始符号 E 的 FOLLOW 包含 <code>$</code>。由 <code>F → ( E )</code>，E 后面还可能是 <code>)</code>，因此：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FOLLOW(E)  = {), $}</span></span>
<span class="line"><span>FOLLOW(E&#39;) = {), $}</span></span>
<span class="line"><span>FOLLOW(T)  = {+, ), $}</span></span>
<span class="line"><span>FOLLOW(T&#39;) = {+, ), $}</span></span>
<span class="line"><span>FOLLOW(F)  = {*, +, ), $}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这些集合通过反复传播直到不再变化得到。对产生式 <code>A → α B β</code>，把 <code>FIRST(β)</code> 中除 ε 外的符号加入 FOLLOW(B)；若 β 可空，再把 FOLLOW(A) 加入 FOLLOW(B)。FOLLOW 集合不包含 ε，因为它描述真实跟随符号或结束标记，而不是“后面什么都没有”的独立 Token。</p><h2 id="_8-4-建立-ll-1-预测表" tabindex="-1">8.4 建立 LL(1) 预测表 <a class="header-anchor" href="#_8-4-建立-ll-1-预测表" aria-label="Permalink to &quot;8.4 建立 LL(1) 预测表&quot;">​</a></h2><p>对每条 <code>A → α</code>，将它放入所有 <code>FIRST(α)</code> 的非空终结符列；若 α 可空，再放入 FOLLOW(A) 的列。空表格表示错误。</p><table tabindex="0"><thead><tr><th>非终结符</th><th>n</th><th>(</th><th>+</th><th>*</th><th>)</th><th>$</th></tr></thead><tbody><tr><td>E</td><td><code>T E&#39;</code></td><td><code>T E&#39;</code></td><td>错误</td><td>错误</td><td>错误</td><td>错误</td></tr><tr><td>E&#39;</td><td>错误</td><td>错误</td><td><code>+ T E&#39;</code></td><td>错误</td><td>ε</td><td>ε</td></tr><tr><td>T</td><td><code>F T&#39;</code></td><td><code>F T&#39;</code></td><td>错误</td><td>错误</td><td>错误</td><td>错误</td></tr><tr><td>T&#39;</td><td>错误</td><td>错误</td><td>ε</td><td><code>* F T&#39;</code></td><td>ε</td><td>ε</td></tr><tr><td>F</td><td><code>n</code></td><td><code>( E )</code></td><td>错误</td><td>错误</td><td>错误</td><td>错误</td></tr></tbody></table><p>每个格子至多一条产生式，因此这份文法是 LL(1)。若一个格子出现两条候选，就存在预测冲突。左因子提取可以解决某些共同前缀问题，消除左递归可以解决某些递归下降问题，但都不是保证任意文法变成 LL(1) 的万能算法。</p><p>手算 <code>n+n*n$</code>：E 展开成 T E&#39;；T 展开成 F T&#39;；F 匹配 n；当前 <code>+</code> 让 T&#39; 选 ε；E&#39; 选 <code>+ T E&#39;</code>；第二个 T 先匹配 n，再因 <code>*</code> 展开 T&#39;，匹配另一个 n；剩余可空部分消失，最后匹配 <code>$</code>。这正好表达乘法比加法先结合。</p><h2 id="_8-5-lr-项目-记住已经看到了哪里" tabindex="-1">8.5 LR 项目：记住已经看到了哪里 <a class="header-anchor" href="#_8-5-lr-项目-记住已经看到了哪里" aria-label="Permalink to &quot;8.5 LR 项目：记住已经看到了哪里&quot;">​</a></h2><p>LR 使用项目中的圆点记录一条产生式已经识别到的位置。例如 <code>E → E + · n</code> 表示已经看见 <code>E +</code>，现在需要一个 n。项目集是分析器状态，closure 补上圆点后非终结符的候选，goto 描述识别一个符号后如何移动圆点。</p><p>为便于完整手算，这里使用更小文法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(0) S&#39; → E</span></span>
<span class="line"><span>(1) E  → E + n</span></span>
<span class="line"><span>(2) E  → n</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>其 LR(0) 项目集为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I0: S&#39; → · E      E → · E + n      E → · n</span></span>
<span class="line"><span>I1: S&#39; → E ·      E → E · + n</span></span>
<span class="line"><span>I2: E → n ·</span></span>
<span class="line"><span>I3: E → E + · n</span></span>
<span class="line"><span>I4: E → E + n ·</span></span>
<span class="line"><span></span></span>
<span class="line"><span>goto(I0,E)=I1   goto(I0,n)=I2</span></span>
<span class="line"><span>goto(I1,+)=I3   goto(I3,n)=I4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>I2 与 I4 是可以归约的状态。SLR 使用产生式左端的 FOLLOW 集合决定在哪些向前看符号上归约。本例 <code>FOLLOW(E) = {+, $}</code>，得到下面的表：</p><table tabindex="0"><thead><tr><th>状态</th><th>n</th><th>+</th><th>$</th><th>goto E</th></tr></thead><tbody><tr><td>0</td><td>移进2</td><td>错误</td><td>错误</td><td>1</td></tr><tr><td>1</td><td>错误</td><td>移进3</td><td>接受</td><td>空</td></tr><tr><td>2</td><td>错误</td><td>按规则2归约</td><td>按规则2归约</td><td>空</td></tr><tr><td>3</td><td>移进4</td><td>错误</td><td>错误</td><td>空</td></tr><tr><td>4</td><td>错误</td><td>按规则1归约</td><td>按规则1归约</td><td>空</td></tr></tbody></table><h2 id="_8-6-手工完成一次移进归约" tabindex="-1">8.6 手工完成一次移进归约 <a class="header-anchor" href="#_8-6-手工完成一次移进归约" aria-label="Permalink to &quot;8.6 手工完成一次移进归约&quot;">​</a></h2><p>输入 <code>n+n$</code>，状态栈最开始只有0，向右为栈顶：</p><table tabindex="0"><thead><tr><th>状态栈</th><th>剩余输入</th><th>动作与含义</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>n+n$</code></td><td>移进n，压入状态2</td></tr><tr><td><code>0 2</code></td><td><code>+n$</code></td><td>用 <code>E→n</code> 归约，弹出一个符号对应状态，查goto得到1</td></tr><tr><td><code>0 1</code></td><td><code>+n$</code></td><td>移进+，压入3</td></tr><tr><td><code>0 1 3</code></td><td><code>n$</code></td><td>移进n，压入4</td></tr><tr><td><code>0 1 3 4</code></td><td><code>$</code></td><td>用 <code>E→E+n</code> 归约，弹出三个状态，再查goto得到1</td></tr><tr><td><code>0 1</code></td><td><code>$</code></td><td>接受</td></tr></tbody></table><p>真正实现通常还维护符号值栈。移进时压入 Token 的语义值，归约时取出右部对应的孩子，创建左部 AST 节点。状态栈决定结构，值栈保存结构对应的数据；它们不能在归约长度上错位。</p><p>左递归文法在 LR 中很自然，不会像天真递归下降那样无限调用自身。这不是因为 LR 会神奇地修复错误文法，而是它先消费输入，再在合适时机把已经看见的右部归约为左部。</p><h2 id="_8-7-slr、lalr-与-lr-1-的差异" tabindex="-1">8.7 SLR、LALR 与 LR(1) 的差异 <a class="header-anchor" href="#_8-7-slr、lalr-与-lr-1-的差异" aria-label="Permalink to &quot;8.7 SLR、LALR 与 LR(1) 的差异&quot;">​</a></h2><p>SLR 用 LR(0) 项目加 FOLLOW 做归约决策，表相对紧凑，但 FOLLOW 汇总了不同上下文，有时会引入冲突。规范 LR(1) 项目把一个向前看 Token 与具体项目上下文绑定，决策更精确，但状态可能更多。LALR 合并具有相同 LR(0) 核的 LR(1) 状态以缩小表，合并后可能引入冲突。</p><p>移进/归约冲突意味着同一状态、同一向前看符号上，既可以移进也可以归约；归约/归约冲突意味着存在两种归约选择。优先级和结合性声明可以为某些冲突规定语言含义，但“让生成器安静下来”不等于文法已经清楚。Bison 官方手册用悬挂 else 展示这个问题。Sprout 要求分支体使用花括号，降低了这类歧义带来的阅读和实现负担。</p><h2 id="_8-8-其他算法放在什么位置" tabindex="-1">8.8 其他算法放在什么位置 <a class="header-anchor" href="#_8-8-其他算法放在什么位置" aria-label="Permalink to &quot;8.8 其他算法放在什么位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>核心思路</th><th>值得注意的边界</th></tr></thead><tbody><tr><td>CYK</td><td>在子串区间上做动态规划</td><td>常用形式要求 Chomsky 标准形；一般时间 O(n³)，空串需额外处理</td></tr><tr><td>Earley</td><td>为每个输入位置维护带圆点项目，进行预测、扫描、完成</td><td>能处理一般 CFG，最坏时间 O(n³)，某些文法类别可更快</td></tr><tr><td>GLR</td><td>在冲突处分叉，共享分析栈与解析森林</td><td>适合保留多种分析，但歧义与资源成本仍需管理</td></tr><tr><td>PEG/Packrat</td><td>有序选择决定先尝试哪个分支，使用记忆化避免重复工作</td><td>有序选择的语义不同于 CFG 的无序选择；内存、左递归支持需单独考虑</td></tr><tr><td>ANTLR</td><td>通过生成器维护语法与目标解析器</td><td>语义与性能依具体工具机制，不等于简单 LL(1) 表</td></tr></tbody></table><p>想象 CYK 的表格：<code>table[i,j]</code> 保存区间 <code>[i,j)</code> 能归约成哪些非终结符；逐渐增加区间长度，枚举切分点。Earley 则把“某条规则在某个起点已经走到哪里”的项目保存在输入位置集合中。它们让你看到：解析不一定是一条确定路径，也可以是组织大量可能结构的动态规划。</p><p>第一次写 Sprout 选择递归下降，是为了让每一行源码与语法规则容易对应。将来接入更复杂现有文法、需要保留二义结构或追求生成器维护能力时，再按需求选择工具。</p><h2 id="_8-9-练习与验收" tabindex="-1">8.9 练习与验收 <a class="header-anchor" href="#_8-9-练习与验收" aria-label="Permalink to &quot;8.9 练习与验收&quot;">​</a></h2><p>练习一：对本章 LL 文法，为什么 <code>FOLLOW(T)</code> 包含 <code>+</code>，却不包含 <code>*</code>？</p><details><summary>查看答案</summary><p>T 后面是 E&#39;，它可以先产生 <code>+</code>。<code>*</code> 则属于 T 内部的 T&#39;，不会跟在已经完整结束的 T 后面。因此 <code>*</code> 出现在 FOLLOW(F)，而不是 FOLLOW(T)。</p></details><p>练习二：用 LR 表手算 <code>n+n+n$</code>，说明两次规则1归约如何产生左结合。</p><details><summary>查看答案</summary><p>识别前两个n后，在看到下一个+时，状态4先按 <code>E→E+n</code> 归约，将 <code>n+n</code> 变成一个E；然后再移进后一个+与n。最终树为 <code>(n+n)+n</code>。</p></details><p>本章验收：能独立重算 FIRST/FOLLOW，解释 LL 表每个非空格的来源，完整跟踪 LR 栈，并准确区分文法冲突与工具实现错误。</p><h2 id="来源与延伸阅读" tabindex="-1">来源与延伸阅读 <a class="header-anchor" href="#来源与延伸阅读" aria-label="Permalink to &quot;来源与延伸阅读&quot;">​</a></h2><p>本地资料定位：<code>compilers-papers-we-love/parsing/InformationAndControl (1965 Knuth) On the Translation of Languages from Left to Right.pdf</code> 前2页；<code>compilers-resources/projects/parser/README.md</code>；论文库 <code>parsing/README.md</code> 提供 Packrat 原作者资料入口。目录中的 Earley、DeRemer、GLR 与 ALL(*) 论文可用于后续专题阅读，未将它们视作本章已逐页研读的材料。</p><p>公开一手资料：<a href="https://www.gnu.org/s/bison/manual/html_node/Shift_002fReduce.html" target="_blank" rel="noreferrer">GNU Bison：Shift/Reduce Conflicts</a>；<a href="https://www.gnu.org/software/bison/manual/html_node/Algorithm.html" target="_blank" rel="noreferrer">GNU Bison：Parser Algorithm</a>；<a href="https://bford.info/packrat/" target="_blank" rel="noreferrer">Bryan Ford 的 Packrat/PEG 资料页</a>；<a href="https://www.antlr.org/doc/" target="_blank" rel="noreferrer">ANTLR 官方文档</a>。本章两套文法、集合和状态表为独立推导。</p>`,51)])])}const L=e(s,[["render",r]]);export{b as __pageData,L as default};
